<template>
 <div class="ai-workspace ai-admin-shell">
  <AiPageHeader title="Cấu hình AI"><template #actions><a href="#ai-data" class="ui-btn ui-btn-secondary">Nguồn dữ liệu</a></template></AiPageHeader>
  <div class="ai-admin-body space-y-4">
  <LoadingSpinner v-if="loading" text="Đang tải cấu hình AI..."/>
  <form v-else @submit.prevent="save" class="space-y-4">
   <p v-if="error" role="alert" class="rounded-xl bg-rose-50 text-rose-800 p-3">{{ error }}</p><p v-if="message" role="status" class="rounded-xl bg-blue-50 text-blue-900 p-3">{{ message }}</p>
   <div class="ai-panel">
    <div class="ai-settings-grid">
     <section class="ai-settings-section space-y-4"><h3 class="ui-section-title">Kết nối nhà cung cấp</h3><div class="flex justify-between items-center gap-3"><span class="ai-muted">Nhà cung cấp</span><strong>{{ providerName }}</strong></div><div><label for="ai-base-url" class="font-semibold">Địa chỉ API</label><input id="ai-base-url" v-model.trim="form.baseUrl" required type="url" maxlength="500" :disabled="busy" class="ai-field"/></div><div v-if="hasKey&&!changeKey" class="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-emerald-200 bg-emerald-50 p-3"><span class="font-semibold text-emerald-800">Đã lưu khóa API</span><button type="button" class="ui-btn ui-btn-secondary" :disabled="busy" @click="changeKey=true">Thay khóa</button></div><div v-if="!hasKey||changeKey"><label for="ai-api-key" class="font-semibold">{{ hasKey?'API key mới':'API key' }}</label><input id="ai-api-key" v-model="form.apiKey" type="password" autocomplete="new-password" spellcheck="false" maxlength="4096" :disabled="busy||form.removeKey" class="ai-field" placeholder="Dán khóa API của nhà cung cấp" aria-describedby="ai-key-help"/><p id="ai-key-help" class="mt-2 ai-muted">{{ hasKey?'Để trống để giữ khóa đang lưu.':'Khóa được lưu trên máy chủ và không hiển thị lại.' }}</p></div></section>
     <section class="ai-settings-section space-y-4"><h3 class="ui-section-title">Mô hình và xử lý dữ liệu</h3><SearchableSelect v-model="form.model" :options="modelOptions" label="Phiên bản AI đọc tài liệu" placeholder="Chọn phiên bản AI" :is-multi="false" :clearable="false" :disabled="busy||modelsLoading"/><div class="flex items-center gap-3 flex-wrap"><button type="button" class="ui-btn ui-btn-secondary" :disabled="busy||modelsLoading||!(hasKey||form.apiKey.trim())||form.removeKey" @click="loadModels">{{ modelsLoading?'Đang lấy danh sách…':'Tải danh sách phiên bản AI' }}</button><span v-if="models.length" class="ai-muted">{{ formatNumber(models.length) }} phiên bản</span></div><p v-if="modelsError" role="alert" class="text-amber-800">{{ modelsError }}</p><label for="ai-enabled" class="flex cursor-pointer items-start gap-3 rounded-xl border border-slate-200 p-4"><input id="ai-enabled" v-model="form.enabled" type="checkbox" class="mt-0.5 h-4 w-4 accent-blue-600" :disabled="busy"/><span><strong>Cho phép AI xử lý dữ liệu</strong><span class="block ai-muted mt-1">Áp dụng cho tài liệu tải lên và bài viết từ Google Alerts.</span></span></label></section>
    </div>
    <footer class="ai-footer"><p>Kiểm tra kết nối có thể phát sinh phí API.</p><div class="ai-footer-actions"><button type="button" class="ui-btn ui-btn-secondary" :disabled="busy||modelsLoading||!form.model||!(hasKey||form.apiKey.trim())||form.removeKey" @click="test">{{ testing?'Đang kiểm tra…':'Kiểm tra kết nối' }}</button><button type="submit" class="ui-btn ui-btn-primary" :disabled="busy||modelsLoading">{{ saving?'Đang lưu…':'Lưu cấu hình AI' }}</button></div></footer>
   </div>
   <details class="ai-panel p-4 sm:p-5"><summary class="cursor-pointer font-semibold text-slate-700">Tùy chọn nâng cao</summary><div class="mt-4 grid md:grid-cols-2 gap-5"><div><label for="ai-model" class="font-semibold">Nhập mã model thủ công</label><input id="ai-model" v-model.trim="form.model" maxlength="200" :disabled="busy" class="ai-field" placeholder="Dùng khi nhà cung cấp không trả danh sách"/><p class="mt-2 ai-muted">API cần hỗ trợ Chat Completions và JSON Schema.</p></div><label v-if="hasKey" for="ai-remove-key" class="flex items-start gap-3 text-rose-800"><input id="ai-remove-key" v-model="form.removeKey" type="checkbox" :disabled="busy" class="mt-1"/>Xóa khóa đang lưu khi bấm Lưu (cần tắt xử lý AI)</label></div></details>
   <section class="ai-panel"><h3 class="ui-section-title p-4 sm:px-5 border-b border-slate-200">Cấu hình đang sử dụng</h3><dl class="ai-settings-summary"><div><dt>Khóa API</dt><dd :class="hasKey?'text-emerald-700':'text-amber-800'">{{ hasKey?'Đã lưu':'Chưa có' }}</dd></div><div><dt>Phiên bản AI</dt><dd>{{ savedModel||'Chưa chọn' }}</dd></div><div><dt>Xử lý dữ liệu</dt><dd><span class="ai-badge" :class="savedEnabled?'bg-blue-50 text-blue-800':'bg-slate-100 text-slate-700'">{{ savedEnabled?'Đang bật':'Đang tắt' }}</span></dd></div><div><dt>Cập nhật gần nhất</dt><dd>{{ updatedAt?formatDateTime(updatedAt):'Chưa lưu' }}</dd><p v-if="updatedBy" class="ai-muted mt-1">{{ updatedBy }}</p></div></dl></section>
  </form>
  </div>
 </div>
</template>
<script setup>
import AiPageHeader from '../components/AiPageHeader.vue';
import {ref,computed,watch,nextTick,onMounted,onUnmounted} from 'vue';
import {fetchWithAuth} from '../services/auth';
import {getApiUrl} from '../config/api';
import {formatDateTime,formatNumber} from '../shared/formatters';
import LoadingSpinner from '../components/LoadingSpinner.vue';
import SearchableSelect from '../components/SearchableSelect.vue';
const loading=ref(true),busy=ref(false),testing=ref(false),saving=ref(false),error=ref(''),message=ref(''),hasKey=ref(false),updatedAt=ref(null),updatedBy=ref(''),changeKey=ref(false),savedModel=ref(''),savedEnabled=ref(false);
const models=ref([]),modelsLoading=ref(false),modelsError=ref('');let modelsVersion=0;
const form=ref({enabled:false,baseUrl:'https://api.openai.com/v1',model:'',apiKey:'',removeKey:false});
const providerName=computed(()=>{try{const host=new URL(form.value.baseUrl).hostname;return host==='api.openai.com'?'OpenAI':host==='generativelanguage.googleapis.com'?'Google Gemini':host;}catch{return 'Kết nối tùy chỉnh';}});
const modelOptions=computed(()=>{const ids=new Set(models.value);if(form.value.model)ids.add(form.value.model);return [...ids].map(id=>({value:id,label:id}));});
async function api(path='',options){const res=await fetchWithAuth(getApiUrl('/api/ai-provider'+path),options);if(!res.ok){const d=await res.json().catch(()=>({}));throw new Error(res.status===404?'Backend chưa cập nhật chức năng cấu hình này.':d.message||`Không xử lý được cấu hình (HTTP ${res.status}).`);}return res.json();}
async function load(){loading.value=true;try{const d=await api();form.value={enabled:d.enabled,baseUrl:d.baseUrl,model:d.model,apiKey:'',removeKey:false};hasKey.value=d.hasApiKey;updatedAt.value=d.updatedAt;updatedBy.value=d.updatedBy;savedModel.value=d.model;savedEnabled.value=d.enabled;changeKey.value=false;await nextTick();}catch(e){error.value=e.message;}finally{loading.value=false;}if(hasKey.value)loadModels();}
async function loadModels(){const request=++modelsVersion;modelsLoading.value=true;modelsError.value='';try{const d=await api('/models',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(form.value)});if(request!==modelsVersion)return;if(!Array.isArray(d.models))throw new Error('Nhà cung cấp chưa trả danh sách AI. Có thể nhập mã trong Tùy chọn nâng cao.');models.value=d.models;if(!models.value.length)modelsError.value='Chưa có phiên bản phù hợp trong danh sách. Kiểm tra quyền API hoặc nhập mã trong Tùy chọn nâng cao.';}catch(e){if(request===modelsVersion)modelsError.value=e.message;}finally{if(request===modelsVersion)modelsLoading.value=false;}}
async function action(kind){if(busy.value||modelsLoading.value)return;busy.value=true;testing.value=kind==='test';saving.value=kind==='save';error.value='';message.value='';try{const result=await api(kind==='test'?'/test':'',{method:kind==='test'?'POST':'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(form.value)});message.value=result.message;if(kind==='save'){form.value.apiKey='';await load();}}catch(e){error.value=e.message;}finally{busy.value=false;testing.value=false;saving.value=false;}}
watch(()=>[form.value.baseUrl,form.value.apiKey],()=>{modelsVersion++;models.value=[];modelsError.value='';modelsLoading.value=false;});
const save=()=>action('save'),test=()=>action('test');onMounted(load);onUnmounted(()=>{modelsVersion++;form.value.apiKey='';});
</script>
